  "更新开发工具包？\n\n要下多少见这一项旁边标的大小（断点续传），装的时候会暂停服务 1–2 分钟。\n你用 pip / npm -g 装进工具包的东西会被保留。": "開発ツールキットを更新しますか？\n\nダウンロード量はこの項目の横に表示されています（レジューム可）。インストール中はサービスが 1〜2 分停止します。\npip / npm -g でツールキットに入れたものは保持されます。",
  "开始": "開始しました",
  "自动更新（默认开）：Claude Code 静默更新；新版应用下载好后提醒安装（有 Shizuku 时空闲自动装）；开发工具包只在 Wi‑Fi 下预先下载，下次打开应用时装上": "自動更新（既定でオン）：Claude Code は静かに更新されます。アプリの新版はダウンロード後にインストールを促します（Shizuku があればアイドル時に自動でインストール）。開発ツールキットは Wi-Fi 接続時のみ事前ダウンロードし、次にアプリを開いたときにインストールします",
  "开启后台保活增强？\n\n会改几项系统设置：幽灵进程上限（影响所有应用）、本应用的电池白名单与后台运行限制。关掉开关会恢复前两项。": "バックグラウンド維持の強化を有効にしますか？\n\nいくつかのシステム設定を変更します：ファントムプロセスの上限（すべてのアプリに影響）、このアプリのバッテリー許可リストとバックグラウンド実行の制限。スイッチを切ると最初の二つは元に戻ります。",
