  "权限模式已改为「逐项确认」，与官方一致：改文件、跑命令前会先问你。想恢复全部放行，点下方的权限标签。": "権限モードを公式と同じ「毎回確認」に変更しました。ファイルの変更やコマンド実行の前に確認します。すべて許可に戻すには、下の権限ラベルをタップしてください。",
