  "等你确认…": "確認待ち…",
  "读文件不问；改文件、跑命令、联网前先问你": "読み取りは確認なし。ファイル変更・コマンド実行・ネット接続の前に確認",
  "改文件不问，跑命令还要问": "ファイル変更は確認なし。コマンド実行は確認",
  "只读和出计划，等你批准再动手": "読み取りと計画のみ。承認後に実行",
  "由 Claude 的分类器判断哪些要问（实验）": "Claude の分類器が確認の要否を判断（実験的）",
  "什么都不问。Claude 可以不经你同意删文件、跑任意命令": "何も確認しません。Claude があなたの同意なしにファイル削除や任意のコマンド実行をできます",
  "切到「全部放行」？\n\nClaude 将不再询问，可以直接改写、删除文件，运行任意命令，访问网络。只在你信任当前任务、且出了事能承受的时候用。": "「すべて許可」に切り替えますか？\n\nClaude は確認せずに、ファイルの書き換え・削除、任意のコマンド実行、ネットワークアクセスを行います。作業内容を信頼でき、万一の結果を受け入れられる場合だけ使ってください。",
  "已切到「{m}」，这一轮当场生效": "「{m}」に切り替えました。このターンから即時に反映されます",
  "已切到「{m}」": "「{m}」に切り替えました",
  "切换权限模式": "権限モードを切り替え",
  "default · 逐项确认（默认）": "default · 毎回確認（既定）",
  "dontAsk · 不询问（要确认的一律拒绝）": "dontAsk · 確認しない（確認が必要なものはすべて拒否）",
  "bypassPermissions · 全部放行": "bypassPermissions · すべて許可",
  "默认逐项确认，和官方一致：改文件、跑命令前会在对话里问你。全部放行意味着 Claude 不问你就能删文件、跑任意命令。也可以点输入框下方的权限标签随时切换。": "既定は公式と同じ毎回確認：ファイル変更やコマンド実行の前に会話内で確認します。すべて許可にすると、Claude は確認なしでファイル削除や任意のコマンド実行ができます。入力欄の下の権限ラベルからいつでも切り替えられます。",
  "↩ 已退回修改": "↩ 修正を依頼しました",
  "在浏览器打开下面的地址完成授权，授权后浏览器跳回本机，登录自动完成：": "下のアドレスをブラウザで開いて認可してください。認可後ブラウザがこの端末に戻り、ログインは自動で完了します：",
  "浏览器跳不回来（比如在别的设备上授权）：打开终端运行 {cmd}，把页面给出的授权码直接贴给 claude。": "ブラウザが戻れない場合（別の端末で認可したときなど）：ターミナルで {cmd} を実行し、ページに表示されたコードを claude に直接貼り付けてください。",
  "浏览器没跳回来（或在别的设备上授权）？在终端里登录：授权码由你直接贴给 claude，本应用不经手。": "ブラウザが戻ってこない（または別の端末で認可した）？ターミナルでログイン：コードは claude に直接貼り付け、このアプリは扱いません。",
