  "要先填：{names}": "先に入力してください：{names}",
  "这个 MCP 服务器会在本机运行下面的 npm 包（注册表里任何人都能发布，没人审核），确认是你信任的来源再继续：\n\n{cmd}": "この MCP サーバーは下の npm パッケージをこの端末で実行します（レジストリには誰でも公開でき、審査はありません）。信頼できる提供元の場合のみ続けてください：\n\n{cmd}",
  "官方技能（anthropics/skills）": "公式スキル（anthropics/skills）",
  "Anthropic 官方的技能仓库，装进 ~/.claude/skills；删除在上面的列表里。各个技能的许可证不同，装前可以点链接看一眼。": "Anthropic 公式のスキルリポジトリ。~/.claude/skills に入れ、削除は上の一覧から行います。スキルごとにライセンスが異なるので、入れる前にリンク先を確認してください。",
  "官方 MCP 注册表": "公式 MCP レジストリ",
  "registry.modelcontextprotocol.io：任何人都能发布，没有人审核。本机能装远程服务和 npm 包；npm 包会在本机运行，装之前看清命令和来源。": "registry.modelcontextprotocol.io：誰でも公開でき、審査はありません。この端末ではリモートサーバーと npm パッケージを入れられます。npm パッケージは端末上で動くので、入れる前にコマンドと提供元を確認してください。",
