  "等你确认时通知（命令、计划、选择题；通知里只能拒绝，允许要回到应用里看完整内容再点）": "確認待ちのとき通知（コマンド・計画・質問。通知からは拒否のみ。許可はアプリで全文を確認してから）",
  "去系统通知设置": "システムの通知設定を開く",
  "系统设置里关掉了本应用的通知，上面的开关不起作用。": "システム設定でこのアプリの通知がオフになっているため、上のスイッチは効きません。",
  "系统设置里关掉了其中一类通知（「等你确认」或「任务完成」）。": "システム設定で一部の通知（「確認待ち」または「タスク完了」）がオフになっています。",
  "这一轮没跑完：App 在后台被系统结束了（{when} 开始的）。": "このターンは完了しませんでした：アプリがバックグラウンドでシステムに終了されました（{when} に開始）。",
  "已经做完的部分都在会话里。点「继续」让 Claude 从断开的地方接着做。": "ここまでの作業は会話に残っています。「続ける」をタップすると、Claude が中断したところから再開します。",
  "会话还没来得及建立，Claude 没收到这条消息。点「重发」把它放回输入框。": "会話がまだ作成されていなかったため、Claude はこのメッセージを受け取っていません。「再送信」で入力欄に戻せます。",
