  "密钥有效（{how}）": "キーは有効です（{how}）",
  "连不上：{err}": "接続できません：{err}",
  "不是 zip 文件": "zip ファイルではありません",
  "zip 目录损坏": "zip のディレクトリが壊れています",
  "不支持的压缩方式：{name}": "対応していない圧縮方式です：{name}",
  "没有可导出的会话": "エクスポートできるセッションがありません",
  "缺少 manifest.json，不是会话包": "manifest.json がありません。セッションのアーカイブではありません",
  "不是 cccodroid 会话包": "cccodroid のセッションアーカイブではありません",
  "（此前的对话已被压缩成摘要）": "（これまでの会話は要約に圧縮されました）",
  "工具包还没装好（或是本地文件装的，没有版本身份），装不了组件": "開発キットのインストールが終わっていない（またはバージョン情報のないローカルファイルから入れた）ため、コンポーネントをインストールできません",
  "没有这个组件": "そのコンポーネントはありません",
  "这个组件只能用在高通骁龙（Adreno GPU）的设备上，本机用不了": "このコンポーネントは Qualcomm Snapdragon（Adreno GPU）搭載機専用のため、この端末では使えません",
  "这个组件还没有对应当前工具包的版本，先更新工具包或稍后再试": "このコンポーネントには、今の開発キットに対応する版がまだありません。キットを更新するか、後でもう一度お試しください",
  "存储空间不够：需要约 {n} MB": "空き容量が足りません：約 {n} MB 必要です",
  "下载的文件校验不符（已删除，重试会重新下载）": "ダウンロードしたファイルの検証に失敗しました（削除済み。再試行すると改めてダウンロードします）",
