  "组件包里的文件校验不符：{file}": "コンポーネントのパッケージ内のファイルが検証に失敗しました：{file}",
  "正在放进工具包，这一步不能中断": "開発キットに配置中です。この手順は中断できません",
  "gh 没装": "gh がインストールされていません",
