  "未配置 API 密钥。请在设置里填入 {name} 的密钥。": "API キーが設定されていません。設定で {name} のキーを入力してください。",
  "本地 DNS 桥启动失败，无法连接 API。": "ローカル DNS ブリッジを起動できなかったため、API に接続できません。",
