  "开发端的 Shizuku 由 Shizuku 应用自己管理（priv 走 rish）": "開発版では Shizuku は Shizuku アプリ自身が管理します（priv は rish 経由）",
  "超时": "タイムアウトしました",
  "版本号不对：{v}": "バージョン番号がおかしいです：{v}",
