  "sha256 不符（期望 {want}…，实得 {got}…）": "sha256 が一致しません（期待値 {want}…、実際 {got}…）",
  "新版试跑失败（--version 得到「{v}」）": "新しい版の試験実行に失敗しました（--version の結果は「{v}」）",
  "开发端只管 Claude Code（应用本体由你在本机构建安装）": "開発版が更新するのは Claude Code だけです（アプリ本体はこの端末で自分でビルドしてインストールします）",
  "没有可装的新版，先检查更新": "インストールできる新しい版がありません。まず更新を確認してください",
  "开始更新 Claude Code": "Claude Code の更新を開始しました",
  "开发端不支持：{op}": "開発版では未対応です：{op}",
  "名字只能用字母、数字、点、下划线、横线": "名前に使えるのは英字・数字・ドット・アンダースコア・ハイフンだけです",
  "缺少命令或地址": "コマンドまたは URL がありません",
  "取不到官方技能目录：{err}": "公式スキル一覧を取得できません：{err}",
  "官方目录里没有这个技能": "公式一覧にそのスキルはありません",
