  "取不到 MCP 注册表：{err}": "MCP レジストリを取得できません：{err}",
  "压缩包里没有 SKILL.md": "アーカイブに SKILL.md がありません",
  "技能名不合法": "スキル名が正しくありません",
  "已有同名技能「{name}」，先删掉旧的": "「{name}」という名前のスキルがすでにあります。先に古いほうを削除してください",
  "这一家正在用，等这一轮跑完再删。": "このプロバイダーは使用中です。このターンが終わってから削除してください。",
  "这一轮还在生成中，等它跑完再切厂商（切换会换掉正在用的密钥与模型）。": "このターンはまだ生成中です。終わってからプロバイダーを切り替えてください（切り替えると使用中のキーとモデルが変わります）。",
  "这个会话正在生成中。": "このセッションは生成中です。",
  "「{name}」还没填 Key。到 设置 → 接口 里填好保存，或换一个接口。": "「{name}」のキーがまだ入力されていません。設定 → エンドポイント で入力して保存するか、別のエンドポイントに切り替えてください。",
  "排队的消息太多了。": "待機中のメッセージが多すぎます。",
  "未知操作": "不明な操作です",
  "这一轮还在生成，等它跑完再退出登录。": "このターンはまだ生成中です。終わってからログアウトしてください。",
  "这一轮已经结束了": "このターンはすでに終わっています",
  "这项已经回答过了": "これにはすでに回答済みです",
  "已允许，下次开机再看": "許可済み、次回起動時に確認",
  "好的，下次开机后再检查。": "了解しました。次回の起動後にもう一度確認します。",
  "另有 {n} 个会话在生成": "ほかに {n} 件の会話が実行中",
  "另一个会话在等你确认 · 打开会话列表查看": "別の会話が確認待ちです · 会話一覧から開いてください",
  "同时在跑的会话已到上限（{max} 个），有空位就依次发出 · 待发 {n} 条": "同時実行の上限（{max} 件）に達しています。空きが出しだい順に送信 · 待機 {n} 件",
  "同时在跑的会话已到上限，已排队，有空位就发出": "同時実行の上限に達しています。キューに入れました。空きが出しだい送信します",
  "等你确认": "確認待ち",
  "最多同时跑几个会话": "同時に実行する会話の上限",
  "不同会话可以同时干活，同一个会话里还是一条接一条。每多跑一个要多占几百 MB 内存，手机内存紧时调小；1 = 一次只跑一轮。": "別々の会話は同時に作業できます。同じ会話の中では今までどおり一つずつ順番です。1 件増えるごとに数百 MB のメモリを使うので、メモリが厳しいときは小さくしてください。1 = 一度に一つ。",
