  "这把 Key 没设额度上限，查不到余额": "このキーには上限がないため、残高は表示できません",
  "每月": "毎月",
  "Coding Plan 套餐额度（智谱没有公开的余额接口，按量计费的 Key 查不到）": "Coding Plan の枠（智譜には公開の残高 API がなく、従量課金のキーは確認できません）",
  "这把 Key 没有 Coding Plan 套餐额度；智谱没有公开的按量余额接口，请到控制台查看": "このキーには Coding Plan の枠がありません。智譜には従量課金の残高を公開する API がないので、コンソールで確認してください",
  "百炼的余额挂在阿里云主账号上，API Key 查不到，请到百炼控制台查看。下面是本机记录的 token 用量。": "百煉（Model Studio）の残高は Alibaba Cloud のメインアカウントに紐づいていて、API キーでは読めません。百煉のコンソールで確認してください。下はこの端末で記録したトークン使用量です。",
  "这个平台没有开放余额查询接口。下面是本机记录的 token 用量。": "このプラットフォームには残高照会 API がありません。下はこの端末で記録したトークン使用量です。",
