  "正常结束。": "正常終了。",
  "拦下（退出码 2）：Claude 这一步不会执行，stderr 里的话会转告它。": "ブロック（終了コード 2）：Claude はこの操作をせず、stderr の内容が伝えられます。",
  "退出码 2：Claude 会接着干，stderr 里的话会转告它。": "終了コード 2：Claude は作業を続け、stderr の内容が伝えられます。",
  "退出码 2：stderr 里的话会反馈给 Claude。": "終了コード 2：stderr の内容が Claude に返されます。",
  "出错了（退出码 {n}）：不会拦下，Claude 照常继续。": "エラー（終了コード {n}）：ブロックはされず、Claude はそのまま続けます。",
  "输出（stdout）": "出力（stdout）",
  "错误输出（stderr）": "エラー出力（stderr）",
  "模拟的输入（可以改了再试）": "模擬入力（書き換えて再実行できます）",
  "再试一次": "もう一度",
