  "还有没解决的冲突，先处理完再切换。": "未解決のコンフリクトがあります。解決してから切り替えてください。",
  "已切到 {b}（{n} 个没提交的改动一起带过来了）": "{b} に切り替えました（未コミットの変更 {n} 件も一緒に移りました）",
