  "没在加载的消息里找到「{q}」": "読み込んだメッセージに「{q}」が見つかりません",
  "选一个已经下好的工具包文件来安装": "ダウンロード済みのツールキットファイルからインストール",
  "本地文件…": "ローカルファイル…",
  "从本地文件安装开发工具包？\n\n选一个 devkit-cc.codroid.tar.gz（或 .tar），可以在 GitHub 发布页或 cccodroid.net 下载。装之前会核对它是不是已发布的版本；装的时候暂停服务 1–2 分钟。\n你用 pip / npm -g 装进工具包的东西会被保留。": "ローカルファイルから開発ツールキットをインストールしますか？\n\ndevkit-cc.codroid.tar.gz（または .tar）を選んでください。GitHub のリリースページか cccodroid.net からダウンロードできます。インストール前に公開版かどうか確認し、インストール中はサービスが 1〜2 分止まります。\npip / npm -g でツールキットに入れたものは残ります。",
  "特权命令记录": "特権コマンドの記録",
  "还没有经 priv 执行过命令": "priv で実行したコマンドはまだありません",
  "最近 {n} 条（最新的在前）。只记在本机，不上传。": "直近 {n} 件（新しい順）。この端末にだけ保存され、アップロードはされません。",
  "{n} 秒后截屏，现在可以切到要截的应用": "{n} 秒後にスクリーンショット。撮りたいアプリに切り替えてください",
