  "5 秒后截屏（先切到要截的应用）": "5 秒後にスクリーンショット（先にアプリへ切り替え）",
  "加载失败：{src}": "読み込みに失敗しました：{src}",
  "用 LibreOffice 转成 PDF 看": "LibreOffice で PDF に変換して表示",
