  "表太大，只显示了前 {r} 行、{c} 列；完整内容请用「原版式」或下载后用别的应用看": "表が大きすぎるため、先頭の {r} 行・{c} 列だけ表示しています。全体は「元のレイアウト」か、ダウンロードして他のアプリで見てください",
