  "第一次打开会慢一些，转好的会缓存起来": "初回は少し時間がかかります。変換結果はキャッシュされます",
  "转换失败": "変換に失敗しました",
  "这种文件要用 LibreOffice 转换后才能看，这里没有 LibreOffice。": "この種類のファイルは LibreOffice で変換しないと表示できませんが、ここには LibreOffice がありません。",
  "看这类文件要先装 LibreOffice（下载约 190 MB，装好约 830 MB）。装一次，以后 PPT、Word、Excel 都能直接看。": "この種類のファイルを見るには、先に LibreOffice をインストールしてください（ダウンロード約 190 MB、インストール後約 830 MB）。一度入れれば PowerPoint・Word・Excel をそのまま開けます。",
  "安装 LibreOffice": "LibreOffice をインストール",
  "正在安装 LibreOffice…可以先去干别的，装好回来再打开。": "LibreOffice をインストール中…ほかの作業をして、終わったら戻ってきてください。",
