  "没装 llama.cpp：到「扩展」页装 llama-cpp 组件": "llama.cpp が入っていません：「拡張」ページで llama-cpp コンポーネントを入れてください",
  "GPU 推理（Vulkan）": "GPU 推論（Vulkan）",
