  "还没有端侧模型：把 .gguf 文件放进 {dir}": "端末上のモデルがまだありません：.gguf ファイルを {dir} に置いてください",
  "正在加载端侧模型 {name}（{how}）…": "端末上のモデル {name} を読み込み中（{how}）…",
