  "删除模型 {name}？": "モデル {name} を削除しますか？",
  "请阅读 {skill}，帮我给端侧小模型配置一个自定义模式。": "{skill} を読んで、端末内モデルのカスタムモードを設定するのを手伝ってください。",
  "还没有模型。到「扩展」页 llama-cpp 组件下的「下载模型」一键下载，或把 .gguf 文件放进上面的目录。": "まだモデルがありません。「拡張」ページの llama-cpp コンポーネントにある「モデルをダウンロード」から取得するか、上のフォルダーに .gguf ファイルを置いてください。",
  "不给工具，提示最短、回得最快": "ツールなし。プロンプト最短で応答も最速",
  "自定义": "カスタム",
  "工具：{tools}": "ツール：{tools}",
  "不给工具": "ツールなし",
  "还没配置": "未設定",
  "配置文件有误，已按聊天模式跑：{msg}": "設定ファイルに誤りがあるため、チャットモードで動作中：{msg}",
  "手机算力有限，小模型干不了活，所以只内置聊天。想自己折腾的话，可以写 {file} 开一个自定义模式（指定工具、系统提示、llama-server 参数）。最省事的办法：切到云端模型，把下面这句发给它：": "スマホの性能では小型モデルに実作業は難しいため、内蔵はチャットのみです。試してみたい場合は {file} を書くとカスタムモード（ツール・システムプロンプト・llama-server の引数）が使えます。いちばん手軽なのは、クラウドモデルに切り替えて次の一文を送ることです：",
  "顶层要是一个对象": "トップレベルはオブジェクトである必要があります",
  "{k} 要是不超过 {n} 字的文本": "{k} は {n} 文字以内のテキストにしてください",
  "llamaArgs 要是文本数组（最多 40 项）": "llamaArgs は文字列の配列（最大 40 個）にしてください",
  "ctx 要是 512 到 262144 之间的整数": "ctx は 512〜262144 の整数にしてください",
  "llamaArgs 里不能改 {k}（由网关管）": "llamaArgs で {k} は変更できません（ゲートウェイが管理）",
  "llama-server 意外退出（rc={code}）": "llama-server が予期せず終了しました（rc={code}）",
  "模型目录写不进去": "モデルフォルダーに書き込めません",
  "目录里没有这个模型": "カタログにないモデルです",
  "没有这个模型": "そのモデルはありません",
  "不在模型目录里": "モデルフォルダー内にありません",
  "会先思考": "先に思考する",
  "偏写代码": "コード向け",
  "偏大": "大きめ",
  "模型放在 /sdcard/cccodroid/models，下好后到 设置 → 模型服务 → 端侧小模型 使用。本机内存 {ram} GB。都是 Q4_K_M 量化；手机上 1–4B 比较实用，超过 6B 会很慢。": "モデルは /sdcard/cccodroid/models に保存され、設定 → モデルサービス → 端末内モデル で使えます。この端末のメモリ：{ram} GB。すべて Q4_K_M 量子化。スマホでは 1〜4B が実用的で、6B を超えるとかなり遅くなります。",
