  "目录里没有的：贴一个 .gguf 文件的下载链接（HuggingFace / 魔搭等）。不校验哈希，只核对文件头。": "一覧にないものは、.gguf ファイルのダウンロードリンク（HuggingFace・ModelScope など）を貼ってください。ハッシュは検証せず、ファイルヘッダーのみ確認します。",
  "{name} 约 {p}B 参数、{size}。手机上会很慢，内存也可能不够。仍然下载？": "{name} は約 {p}B パラメータ（{size}）です。スマホではかなり遅く、メモリが足りない可能性もあります。それでもダウンロードしますか？",
