  "只对 Claude 账户和 Anthropic API Key 生效。上下文超过 20 万 token 的会话闲置约 54 分钟、1 小时提示缓存快过期时，先压缩一次；回来接着聊就不用把整段历史按全价重新处理，订阅账户少占额度，API Key 少花钱。电脑上的 Claude Code 也是这么做的。": "Claude アカウントと Anthropic API キーでのみ有効です。20 万トークンを超える会話が約 54 分アイドルになり、1 時間のプロンプトキャッシュが切れそうになると、一度圧縮します。再開時に履歴全体を定価で処理し直さずに済み、サブスクリプションの使用量も API キーの費用も抑えられます。デスクトップ版 Claude Code も同じ動作です。",
