  "用起来有问题、有想法，欢迎进群聊。报 bug 最好走「设置 → 到 GitHub 反馈」，机型和自检结果会自动带上，群里消息一多就沉了。": "使っていて困ったことやアイデアがあれば、グループで気軽にどうぞ。バグ報告は「設定 → GitHub で報告」から送ると、機種と自己診断の結果が自動で入り、チャットに埋もれません。",
  "这个项目目前只有作者一个人在维护，非常需要帮手：译文校对、机型适配报告、组件配方、文档、代码都欢迎，不会写代码也能帮上忙。怎么参与见仓库里的贡献指南。": "このプロジェクトは今のところ作者ひとりで保守していて、手伝いをとても必要としています。翻訳の校正、機種ごとの動作報告、コンポーネントのレシピ、ドキュメント、コード、どれも歓迎です。コードが書けなくても手伝えます。参加方法はリポジトリの貢献ガイドをご覧ください。",
