  "调用时和其他工具一样，按你选的权限模式确认。会打开别的应用的只是预填，保存、发送、拨出都由你在那个应用里点。": "呼び出しはほかのツールと同じく、選んだ権限モードに従って確認します。ほかのアプリを開くものは入力を済ませるだけで、保存・送信・発信はそのアプリであなたが押します。",
