  "还没激活 Shizuku，应用没法自己开关无障碍：去系统无障碍设置里手动打开 cccodroid。安卓 13 起，侧载的应用要先在 应用信息 → 右上角菜单 → 允许受限设置。": "Shizuku が有効でないため、アプリ自身ではユーザー補助をオン・オフできません。システムのユーザー補助設定で cccodroid をオンにしてください。Android 13 以降、サイドロードしたアプリは先に アプリ情報 → 右上のメニュー → 制限付き設定を許可 が必要です。",
