  "默认关。让 Claude 测你自己做的 App、或把它生成的文件发到别的应用时再打开；开着时每轮对话会多带一两千 token 的工具说明。": "既定はオフ。自作アプリを Claude にテストさせたいときや、作ったファイルをほかのアプリに送りたいときにオンにしてください。オンの間は毎ターン 1〜2 千トークン分のツール説明が加わります。",
