  "工具包是从本地文件装的，不知道该去哪个 Release 下载模块。请先在设置里更新一次工具包": "ツールキットがローカルファイルからインストールされているため、モジュールをどのリリースから取得すればよいかわかりません。先に設定からツールキットを一度更新してください",
  "存储空间不够：需要约 {need} MB，只剩 {free} MB": "空き容量が足りません：約 {need} MB 必要ですが、残りは {free} MB です",
