  "模块包里的文件校验不符：{file}": "モジュールパッケージ内のファイルの検証に失敗しました：{file}",
  "当前是整包工具包，没有模块可卸": "現在のツールキットは一体型なので、アンインストールできるモジュールはありません",
  "基础模块不能卸载": "基本モジュールはアンインストールできません",
  "共享运行库跟着用它的模块走，不能单独卸载": "共有ライブラリはそれを使うモジュールと一緒に入れ替わるため、単独ではアンインストールできません",
  "有模块正在安装，等它结束再试": "モジュールをインストール中です。終わってからもう一度試してください",
  "工具包模块": "ツールキットのモジュール",
  "开发工具包按用途拆成模块，用得上的才装。基础模块必装；共享运行库跟着用它的模块自动装卸。": "開発ツールキットは用途ごとのモジュールに分かれています。必要なものだけインストールしてください。基本モジュールは必須で、共有ライブラリはそれを使うモジュールに合わせて自動でインストール・削除されます。",
  "主要命令：": "主なコマンド：",
  "待发 {n} 条 · 这个会话的上一轮还没完全结束（后台任务在跑或正在收尾），结束后依次发出": "送信待ち {n} 件 · この会話の前のターンがまだ終わりきっていません（バックグラウンドタスク実行中か後処理中）。終わり次第順に送ります",
  "已排队：这个会话的上一轮还没完全结束，结束后发出": "キューに追加：この会話の前のターンがまだ終わりきっていません。終わり次第送ります",
  "卸载开发工具包？\n\n会删掉整个工具包，连同装在里面的组件、加装的模块、你用 pip / npm -g / pkg 装的东西，然后回到首次安装，重新选下载来源和模块。\n\n会话、工作区、登录和设置都保留。正在跑的终端会被关掉。": "開発ツールキットをアンインストールしますか？\n\nツールキット全体を、その中に入れたコンポーネント、追加したモジュール、pip / npm -g / pkg で入れたものごと削除し、初回セットアップに戻ってダウンロード元とモジュールを選び直します。\n\n会話・ワークスペース・ログイン・設定はそのまま残ります。開いているターミナルは閉じられます。",
  "卸载 Claude Code？\n\n删掉已下载的 Claude Code 程序，之后不会自动装回。要用时在这里点「安装…」，自己选版本（stable、latest 或具体版本号）。\n\n登录、会话和设置都保留；没装的时候发消息会提示先安装。": "Claude Code をアンインストールしますか？\n\nダウンロード済みの Claude Code を削除し、自動では入れ直しません。使うときはここで「インストール…」を押し、バージョン（stable、latest、または具体的な番号）を選んでください。\n\nログイン・会話・設定はそのまま残ります。未インストールのままメッセージを送ると、先にインストールするよう案内します。",
  "旧工具包留下的 {n} 个程序（{size}）已隔离，{d} 天后自动删除。": "旧ツールキットが残した {n} 個のプログラム（{size}）を隔離しました。{d} 日後に自動で削除します。",
