  "安装包里的 glibc 加载器和工具包里的不是同一版，经加载器暂时用不了：先更新工具包": "パッケージ内の glibc ローダーがツールキットのものと同じ版ではないため、ローダー経由はまだ使えません。先にツールキットを更新してください",
  "安装包方案": "インストールパッケージ",
  "targetSdk 28 是默认的那套，兼容性最好；targetSdk 36 给系统不让装 28 的新机器用。两套功能一样，数据通用，互相覆盖安装不丢东西。自动：跟着现在装的走，系统拒装 28 时自动换成 36。": "targetSdk 28 が標準で、互換性が最も高い版です。targetSdk 36 は 28 をインストールできない新しい端末向けです。機能は同じでデータも共通なので、上書きインストールしても何も失われません。自動：今入っている方に合わせ、システムが 28 を拒否したら 36 に切り替えます。",
  "现在装的是 targetSdk {n}": "現在のパッケージ：targetSdk {n}",
  "下次更新换成 targetSdk {n}": "次回の更新で targetSdk {n} に切り替え",
  "系统已不让装 targetSdk 28，只能用 36": "このシステムでは targetSdk 28 をインストールできないため、36 のみ使えます",
  "换成 targetSdk {n} 的安装包？\n\n会下载同一版本的另一套安装包（约 14 MB）覆盖安装，对话、设置、工具包都保留。安装时应用会重启一次。": "targetSdk {n} のパッケージに切り替えますか？\n\n同じバージョンのもう一方のパッケージ（約 14 MB）をダウンロードして上書きインストールします。会話・設定・ツールキットはそのまま残ります。インストール中にアプリが一度再起動します。",
  "有 {n} 项可更新": "{n} 件の更新があります",
  "上下文压缩线": "コンテキスト圧縮ライン",
  "交给 claude": "claude に任せる",
  "用量逼近这条线时自动摘要历史。线放低更省、记得更少；放高记得多，但每轮更贵、更慢。": "使用量がこのラインに近づくと履歴を自動で要約します。低くすると節約になるが覚える量が減り、高くすると多く覚えるが毎ターン高く遅くなります。",
  "{line} · 窗口的 {pct}%": "{line} · ウィンドウの {pct}%",
