  "状态": "状態",
  "用订阅账户跑定时任务默认关闭": "サブスクリプションアカウントでの定期タスク実行は既定でオフです",
  "「{n}」要用订阅账户跑：到定时任务页底部「订阅账户」里打开（无人值守使用以 Anthropic 条款为准），或给任务换一个用 API Key 的接口": "「{n}」はサブスクリプションアカウントで実行されます。定期タスク画面下部の「サブスクリプションアカウント」でオンにするか（無人での利用は Anthropic の規約に従います）、API キーを使う接続先に変更してください",
  "订阅账户": "サブスクリプションアカウント",
  "允许用订阅账户跑": "サブスクリプションアカウントでの実行を許可",
  "官方登录的订阅账户默认不跑定时任务。打开前请自己确认：无人值守使用以 Anthropic 条款为准。用 API Key 的接口不受影响。": "公式ログインのサブスクリプションアカウントでは既定で定期タスクを実行しません。オンにする前にご自身で確認してください：無人での利用は Anthropic の規約に従います。API キーを使う接続先には影響しません。",
  "{n} 个任务会用订阅账户，现在不会跑": "{n} 件のタスクがサブスクリプションアカウントを使うため、今は実行されません",
  "订阅账户 · 不会跑": "サブスク · 実行されません",
  "用订阅账户跑定时任务？\n\n定时任务会在没人看着的时候自动跑。无人值守使用以 Anthropic 条款为准，请自己确认你的用法符合条款；条款以后收紧，这一项可能要关掉。": "サブスクリプションアカウントで定期タスクを実行しますか？\n\n定期タスクは誰も見ていないときに自動で実行されます。無人での利用は Anthropic の規約に従います。ご自身の使い方が規約に沿っているか確認してください。規約が厳しくなった場合は、オフにする必要があるかもしれません。",
  "已允许用订阅账户跑定时任务": "サブスクリプションアカウントでの定期タスク実行を許可しました",
  "已关闭：订阅账户不跑定时任务": "オフにしました：サブスクリプションアカウントでは定期タスクを実行しません",
  "「已验证」：维护者在真机上跑过这一版（下载、调用工具、接着上次的会话）。标了「有已知问题」的版本，自动更新不会装。": "「検証済み」：メンテナーが実機でこのバージョンを動かしました（ダウンロード、ツール呼び出し、前回の会話の再開）。「既知の問題あり」のバージョンは自動更新でインストールされません。",
  "真机验证过：{who}": "実機で検証済み：{who}",
  "有已知问题：{why}": "既知の問題：{why}",
  "{v} 已修": "{v} で修正済み",
  "已验证": "検証済み",
  "还没验证": "未検証",
  "{v} 有已知问题：{why}\n\n仍然换到这一版？": "{v} には既知の問題があります：{why}\n\nそれでもこのバージョンに切り替えますか？",
  "等 {n} 台": "ほか計 {n} 台",
  "统计字数…": "文字数を数えています…",
  "工作岛（ColorOS 灵动岛）": "ワークアイランド（ColorOS）",
  "把 Claude 的工作状态显示在 ColorOS 16 的流体云 / 灵动岛上": "Claude の作業状況を ColorOS 16 の流体クラウドに表示します",
  "需要另外安装「工作岛」应用。开启后，正在干活、等待确认、任务完成会出现在岛上的胶囊里；完成后 8 秒自动收起。目前仅在 ColorOS 16 / Android 16 上测试过。": "別途「ワークアイランド」アプリが必要です。オンにすると、作業中・確認待ち・完了がアイランドのカプセルに表示され、完了から 8 秒で自動的に閉じます。現在 ColorOS 16 / Android 16 でのみ確認済みです。",
