  "补档没跑成：{e}": "題名の補完を実行できませんでした：{e}",
  "补好 {n} 章题名": "{n} 章に題名を付けました",
  "，{n} 章没起成": "、{n} 章は失敗",
  "补档 · {n} 章": "題名を補う · {n} 章",
  "用全局默认的 {m}（{p}）给 {s} 个会话的 {c} 章补起题名。": "グローバル既定の {m}（{p}）で、{s} 個のセッションの {c} 章に題名を付けます。",
  "素材是每章结束时的压缩摘要，不重读全文。预计 {k} 次调用，输入约 {i} token、输出约 {o} token（按上限估，实际通常更少）。": "素材は各章の終わりの圧縮要約で、全文は読み直しません。約 {k} 回の呼び出し、入力約 {i}・出力約 {o} トークン（上限での見積もり。実際は通常より少なめ）。",
  "补出来的题名随时能改，之后 AI 建档也会盖过它。开始吗？": "付けた題名はいつでも変更でき、後で AI 自身の記録が上書きします。開始しますか？",
