  "帮我把照片按日期分文件夹": "写真を日付ごとのフォルダに分けて",
  "在真脉络里，这会跳到会话里第 {n} 章的开头。": "実際の系譜では、そのセッションの第 {n} 章の冒頭に移動します。",
  "在真脉络里，这里会弹出「{t}」的章节，点一卷就跳到那一章的开头。": "実際の系譜では「{t}」の章一覧が開き、選ぶとその章の冒頭に移動します。",
  "导览里的按钮不做事，回真脉络再点。": "ツアー内のボタンは動作しません。実際の系譜で使ってください。",
