  "任务所在的项目已经删掉了：编辑任务重新选个项目": "タスクのプロジェクトは削除されました：タスクを編集してプロジェクトを選び直してください",
  "「{n}」所在的项目已经删掉了：编辑任务重新选个项目": "「{n}」のプロジェクトは削除されました：タスクを編集してプロジェクトを選び直してください",
