  "这个会话原来用的接口「{id}」已经删掉了，这一轮没有发出去。在模型面板里换一家再发。": "この会話で使っていたエンドポイント「{id}」は削除されたため、このターンは送信されませんでした。モデルパネルで別のエンドポイントを選んでから送信してください。",
  "项目默认的接口「{id}」已经删掉了，这一轮没有发出去。到项目设置里重新选个接口。": "プロジェクトの既定エンドポイント「{id}」は削除されたため、このターンは送信されませんでした。プロジェクト設定でエンドポイントを選び直してください。",
  "任务指定的接口已经删掉了：编辑任务重新选个接口": "タスクで指定したエンドポイントは削除されました。タスクを編集して選び直してください",
  "「{n}」指定的接口已经删掉了：编辑任务重新选个接口": "「{n}」で指定したエンドポイントは削除されました。タスクを編集して選び直してください",
  "钩子（{ev}）注入的文字命中破甲特征，这一轮已中止；注入原文折叠在上方。": "フック（{ev}）が注入したテキストが脱獄パターンに一致したため、このターンを中止しました。注入された原文は上に折りたたんであります。",
