  "文件太大（{size}），不适合在应用里直接解析；可以用「原版式」转成 PDF 看，或下载后用别的应用打开。": "ファイルが大きすぎる（{size}）ため、アプリ内で直接解析できません。「元のレイアウト」で PDF に変換するか、ダウンロードして他のアプリで開いてください。",
