  "安全模式下不问人的几档不生效，现在是「逐项确认」": "セーフモードでは確認を省くモードは反映されず、現在は「毎回確認」です",
  "设置没保存上，重启后会回到原来的权限模式": "設定を保存できませんでした。再起動すると元の権限モードに戻ります",
