  "换了主机，旧 Key 已清掉，请重新填": "接続先が変わったため古い API キーを消去しました。もう一度入力してください",
  "已过重置时间，下一轮对话后刷新": "リセット時刻を過ぎました。次のメッセージの後に更新されます",
  "项目已创建；目录里已有 CLAUDE.md，填的指令没写进去": "プロジェクトを作成しました。フォルダに既に CLAUDE.md があったため、入力した指示は書き込まれていません",
