  "登录还在进行，拿到授权地址后会自动打开。": "ログインは進行中です。認証アドレスが届き次第自動で開きます。",
  "删掉模型「{id}」？文件会从模型目录里删除。": "モデル「{id}」を削除しますか？モデルフォルダーからファイルが削除されます。",
