  "工具包更新过，暂无适配版本": "ツールキットが更新されました。対応版はまだありません",
  "工具包更新过，组件库里暂时没有适配当前工具包的版本；先更新工具包，或点「检查更新」重新拉一次清单。": "ツールキットが更新されましたが、コンポーネント一覧に現在のツールキットに対応するビルドがまだありません。まずツールキットを更新するか、「更新を確認」を押して一覧を取り直してください。",
  "压缩线最小 100k，已按 100k 存": "圧縮ラインの最小は 100k です。100k で保存しました",
  "安装记录写不进去（存储满了或没有权限），这次安装没有继续": "インストール記録を書き込めませんでした（容量がいっぱいか権限がありません）。今回のインストールは続行しませんでした",
  "文件已放进去了，但安装记录没写成（存储满了或没有权限），请重装或卸载": "ファイルは配置済みですが、インストール記録を書き込めませんでした（容量がいっぱいか権限がありません）。再インストールかアンインストールをしてください",
  "组件记录没写进去（存储满了或没有权限），这次安装没有完成": "コンポーネントの記録を書き込めませんでした（容量がいっぱいか権限がありません）。今回のインストールは完了していません",
  "地址回了 {s}，但不是预期的格式，没法确认密钥有效：{what}": "エンドポイントは {s} を返しましたが、想定した形式ではないためキーの有効性を確認できません：{what}",
  "（空）": "（空）",
  "上游在回答结尾报了错（{msg}），已按说完处理；如果回答不完整，发一句「继续」": "上流が回答の最後でエラーを返しました（{msg}）。完了として扱いました。回答が途中で切れていれば「続けて」と送ってください",
  "{name} 原来选的线路「{ep}」已经不在了。请到设置里重选线路，并重新填这条线路的密钥。": "{name} で選んでいた回線「{ep}」はもうありません。設定で回線を選び直し、その回線のキーを入力し直してください。",
  "这个地址是明文 http，密钥和对话内容会不加密地发到对方机器上；能用 https 就换成 https。": "このアドレスは平文の http です。キーと会話内容が暗号化されずに相手のマシンへ送られます。可能なら https に切り替えてください。",
  "定时任务要单独跑一轮：挪到最前，这一轮结束后马上发出": "スケジュールタスクは単独のターンで実行されます：先頭に移動し、現在のターンが終わり次第開始します",
  "到上限后当天其余任务跳过，并通知你。只算官方接口的花费：第三方端口不计花费，每日上限对它不生效。": "上限に達すると当日の残りのタスクはスキップされ、通知します。公式 API の費用だけを数えます：サードパーティのエンドポイントは費用を計上しないため、1 日の上限は適用されません。",
  "超了就停，记成失败；只对官方接口生效": "超えたら停止し、失敗として記録します。公式 API にのみ適用",
  "这个任务用的是第三方端口：不计花费，单次花费上限和每日上限对它都不生效，靠时长上限兜底。": "このタスクはサードパーティのエンドポイントを使います：費用は計上されないため、1 回あたりの費用上限も 1 日の上限も適用されず、時間上限が歯止めになります。",
  "原来选的线路已不在了（厂商目录更新删了它），旧 Key 不会带到新线路：请重选线路、重新填 Key 后保存。": "以前選んだ経路はなくなりました（プロバイダー一覧の更新で削除されました）。古いキーは新しい経路に引き継がれません：経路を選び直し、キーを入れ直して保存してください。",
  "换了线路，旧 Key 已清掉，请重新填": "経路を変えたため古いキーを消去しました。もう一度入力してください",
