  "安装期间有 {n} 个共享文件被卸载删掉了，请重新安装": "インストール中に {n} 個の共有ファイルがアンインストールで削除されました。もう一度インストールしてください",
  "会话钉住的端侧模型 {model} 已经不在了，请在模型面板重新选一个": "このセッションに固定した端末上のモデル {model} はもうありません。モデルパネルで選び直してください",
