  "系统不允许本应用启动工作岛服务，所以没有显示。": "システムがこのアプリからのワークアイランドサービスの起動を許可していないため、表示されません。",
  "没检测到「工作岛」应用：装好后点重试。": "「ワークアイランド」アプリが見つかりません。インストールしてから再試行を押してください。",
  "本机自检": "端末のセルフテスト",
  "把工具包里的编译器、Python、Node、git 等逐项跑一遍，结果会告诉 Claude 这台设备上什么能用、什么不能用。工具包或应用更新后会自动重测；修好了什么、想马上让 Claude 知道，就点重新自检。": "開発キットのコンパイラー、Python、Node、git などを順に実行し、この端末で何が使えて何が使えないかを Claude に伝えます。開発キットやアプリの更新後は自動で再テストします。何かを直してすぐ Claude に知らせたいときは「セルフテストを再実行」を押してください。",
