  "这一轮没跑完：App 更新时网关重启了（{when} 开始的）。": "このターンは完了していません：アプリの更新中にゲートウェイが再起動しました（{when} に開始）。",
  "这一轮没跑完：网关被关闭或重启了（{when} 开始的）。": "このターンは完了していません：ゲートウェイが停止または再起動されました（{when} に開始）。",
  "工作目录 {dir} 不在了（被删、改名或存储卡拔出了），这一轮没有运行。把目录放回去，或者到项目设置里改路径后再发。": "作業フォルダー {dir} が見つかりません（削除・名前変更、またはストレージカードが外された）。このターンは実行していません。フォルダーを戻すか、プロジェクト設定でパスを変更してから送信し直してください。",
  "这一轮还没开始就被结束了（{when} 发的）。": "このターンは開始前に終了しました（{when} に送信）。",
