  "对话太长，超过了模型的上下文上限。打 /compact 压缩一下再继续，或者开个新对话。": "会話がモデルのコンテキスト上限を超えています。/compact で圧縮してから続けるか、新しい会話を始めてください。",
  "接口拒绝了密钥：到 设置 → 接口 检查 API Key 填得对不对、有没有过期或被停用。": "エンドポイントがキーを拒否しました：設定 → エンドポイント で API キーが正しいか、期限切れや無効化されていないか確認してください。",
  "账户余额不足或额度用完了：到接口那边的控制台充值或查看额度。": "残高不足またはクォータを使い切りました：提供元のコンソールでチャージするか、クォータを確認してください。",
  "请求太频繁，或者用量到了上限：稍等一会儿再试。": "リクエストが多すぎるか、使用量の上限に達しました：少し待ってから再試行してください。",
  "接口找不到这个模型或地址：检查模型名和接口地址。": "エンドポイントがこのモデルまたはアドレスを見つけられません：モデル名とエンドポイント URL を確認してください。",
  "接口那边出错或者忙不过来：稍后再试。一直这样就换个模型或接口。": "提供元でエラーが起きたか混雑しています：しばらくして再試行してください。続く場合は別のモデルかエンドポイントに切り替えてください。",
